func testMoedaToManyAddOpMoedaCotacaos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Moeda
	var b, c, d, e MoedaCotacao

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, moedaDBTypes, false, strmangle.SetComplement(moedaPrimaryKeyColumns, moedaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*MoedaCotacao{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, moedaCotacaoDBTypes, false, strmangle.SetComplement(moedaCotacaoPrimaryKeyColumns, moedaCotacaoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*MoedaCotacao{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddMoedaCotacaos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.MoedaID != first.MoedaID {
			t.Error("foreign key was wrong value", a.MoedaID, first.MoedaID)
		}
		if a.MoedaID != second.MoedaID {
			t.Error("foreign key was wrong value", a.MoedaID, second.MoedaID)
		}

		if first.R.Moeda != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Moeda != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.MoedaCotacaos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.MoedaCotacaos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.MoedaCotacaos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
